        if path == "/reference.css":
            refcss = Path("/media/domenicleonetti/easystore/EIRA/LIVE/eira2_server_revamp/static/reference.css")
            if refcss.is_file():
                return self._bytes(200, refcss.read_bytes(), "text/css; charset=utf-8", cache="no-cache")
        if path == "/reference.js":
            p = Path("/media/domenicleonetti/easystore/EIRA/LIVE/eira2_server_revamp/static/reference.js")
            if p.is_file():
