            return self._static("communication.js", "application/javascript; charset=utf-8")
        if path == "/neural/invention.js":
            return self._static("invention.js", "application/javascript; charset=utf-8")
        if path == "/neural/style.css":
            return self._static("style.css", "text/css; charset=utf-8")
        if path == "/neural/invention.css":
            return self._static("invention.css", "text/css; charset=utf-8")
        if path == "/neural/ar-placeholder.svg":
            return self._static("ar-placeholder.svg", "image/svg+xml")

        if path == "/health":
            overview = self.surface.atlas.overview()
            return self._json(
                200,
                {
                    "ok": True,
                    "service": "eira2.neural",
                    "inventory_neuron_count": overview["inventory_neuron_count"],
                    "conductive_fiber_count": overview["conductive_fiber_count"],
                    "tracer_enabled": self.surface.activity.enabled,
                    "invention_usdz_quick_look": True,
                },
            )

        if path == "/api/inventions/usdz":
            return self._json(200, self._list_usdz())

        usdz_prefix = "/inventions/usdz/"
        if path.startswith(usdz_prefix):
            name = unquote(path[len(usdz_prefix):])
            if "/" in name or "\\" in name or not name.casefold().endswith(".usdz"):
                return self._json(400, {"ok": False, "error": "invalid_usdz_name"})
            return self._serve_file(self.surface.invention_usdz_root / name, "model/vnd.usdz+zip", filename=name)

        if path == "/api/neural/overview":
            return self._json(200, self.surface.atlas.overview())

        if path == "/api/neural/nodes":
            cluster = (query.get("cluster") or [None])[0]
            cursor = self._int(query, "cursor", 0)
            limit = self._int(query, "limit", 1500)
            include_paths = (query.get("paths") or ["1"])[0] not in {"0", "false", "no"}
            return self._json(
                200,
                self.surface.atlas.page(
                    cluster=cluster,
                    cursor=cursor,
                    limit=limit,
                    include_paths=include_paths,
                ),
            )

        if path == "/api/neural/fibers":
            cluster = (query.get("cluster") or [None])[0]
            limit = self._int(query, "limit", 20000)
            return self._json(200, self.surface.atlas.fibers_for(cluster=cluster, limit=limit))

        if path == "/api/neural/activity":
            try:
                window = float((query.get("window") or ["2.4"])[0])
            except (TypeError, ValueError):
                window = 2.4
            limit = self._int(query, "limit", 400)
            return self._json(200, self.surface.activity.snapshot(window_seconds=window, limit=limit))

        if path == "/api/neural/search":
            term = (query.get("q") or [""])[0]
            limit = self._int(query, "limit", 100)
            return self._json(200, self.surface.atlas.search(term, limit=limit))

        prefix = "/api/neural/neuron/"
        if path.startswith(prefix):
            neuron_id = unquote(path[len(prefix):])
            row = self.surface.atlas.neuron(neuron_id)
            if row is None:
                return self._json(404, {"ok": False, "error": "neuron_not_found"})
            return self._json(200, {"ok": True, "schema": "eira2_neuron_detail_v1", "neuron": row})

        self._json(404, {"ok": False, "error": "not_found"})


class NeuralHTTPServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, address: tuple[str, int], surface: NeuralSurface) -> None:
        self.surface = surface
        super().__init__(address, NeuralHandler)


class NeuralHTTPService:
    spec = ServiceSpec(
        "interfaces.neural_ui",
        required=False,
        dependencies=("kernel.events",),
        start_timeout_seconds=45.0,
        stop_timeout_seconds=10.0,
    )

    def __init__(
        self,
        root: Path,
        *,
        host: str = "127.0.0.1",
        port: int = 8782,
        inventory: Path | None = None,
        trace: bool = True,
    ) -> None:
        self.root = root.expanduser().resolve()
        self.host = host
        self.port = int(port)
        self.surface = NeuralSurface(self.root, inventory=inventory, trace=trace)
        self._state = ServiceState.DECLARED
        self._server: NeuralHTTPServer | None = None
        self._thread: threading.Thread | None = None

    @property
    def url(self) -> str:
        return f"http://{self.host}:{self.port}/neural/"

    async def start(self, context: RuntimeContext) -> None:
        self.surface.start()
        server = NeuralHTTPServer((self.host, self.port), self.surface)
        self.port = int(server.server_address[1])
        self._server = server
        self._thread = threading.Thread(
            target=server.serve_forever,
            name="eira2-neural-http",
            kwargs={"poll_interval": 0.2},
            daemon=True,
        )
        self._thread.start()
        self._state = ServiceState.READY

    async def stop(self) -> None:
        if self._server is not None:
            self._server.shutdown()
            self._server.server_close()
        if self._thread is not None:
            self._thread.join(timeout=3.0)
        self.surface.stop()
        self._server = None
        self._thread = None
        self._state = ServiceState.STOPPED

    async def health(self) -> Health:
        detail = self.url if self._state == ServiceState.READY else ""
        return Health(self._state, detail)


def run(root: Path, host: str, port: int, inventory: Path | None, trace: bool) -> None:
    surface = NeuralSurface(root, inventory=inventory, trace=trace)
    surface.start()
    server = NeuralHTTPServer((host, port), surface)
    actual_port = int(server.server_address[1])
    print(f"EIRA 2.0 neural surface: http://{host}:{actual_port}/neural/", flush=True)
    try:
        server.serve_forever(poll_interval=0.2)
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        surface.stop()


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", type=Path, default=Path.cwd())
    parser.add_argument("--host", default=os.getenv("EIRA2_NEURAL_HOST", "127.0.0.1"))
    parser.add_argument("--port", type=int, default=int(os.getenv("EIRA2_NEURAL_PORT", "8782")))
    parser.add_argument("--inventory", type=Path, default=None)
    parser.add_argument("--no-trace", action="store_true")
    args = parser.parse_args()
    run(args.root.resolve(), args.host, args.port, args.inventory, not args.no_trace)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

